      local: "número do local de votação (único por zona e município)", aptos: "eleitores aptos", comparecimento: "eleitores que votaram", faltosos: "eleitores que faltaram",
      abertura: "hora de abertura (hora local, HH:MM:SS)", encerramento: "hora de encerramento (hora local)", agregadas: "seções agregadas, se houver",
