    cq_tabelas_t: "Tables and columns", cq_ops: { "=": "equal to", "!=": "not equal to", ">": "greater than", ">=": "greater than or equal to", "<": "less than", "<=": "less than or equal to", like: "contains" },
    cq_desc_tab: { secoes: "one row per section and round", sinalizacoes: "one row per section, round and test", locais: "one row per polling place", candidatos: "presidential candidates in each round", testes: "the 15 tests", municipios: "municipalities" },
    cq_ex: [
      ["Sections with 100% for one candidate (round 2)", "SELECT uf, municipio, zona, secao, aptos, comparecimento, v13, v22\nFROM secoes\nWHERE turno = 2 AND validos >= 10 AND (v13 = validos OR v22 = validos)\nORDER BY validos DESC"],
      ["Turnout by municipality (round 2)", "SELECT uf, municipio, COUNT(*) AS secoes, SUM(aptos) AS aptos, SUM(comparecimento) AS votaram,\n  ROUND(100.0 * SUM(comparecimento) / SUM(aptos), 2) AS comparecimento_pct\nFROM secoes WHERE turno = 2\nGROUP BY uf, municipio ORDER BY comparecimento_pct DESC"],
      ["Machines that closed after 6 p.m. (local time)", "SELECT uf, municipio, zona, secao, turno, abertura, encerramento\nFROM secoes WHERE encerramento >= '18:00:00'\nORDER BY encerramento DESC"],
      ["Flags by test and state", "SELECT s.turno, s.teste, t.nome, s.uf, COUNT(*) AS ocorrencias\nFROM sinalizacoes s JOIN testes t ON t.id = s.teste\nGROUP BY s.turno, s.teste, s.uf ORDER BY ocorrencias DESC"],
      ["Places with the most sections", "SELECT l.uf, m.nome AS municipio, l.zona, l.local, l.nome, l.bairro, l.secoes\nFROM locais l JOIN municipios m ON m.uf = l.uf AND m.codigo = l.cod_mun\nORDER BY l.secoes DESC"],
      ["Difference between sections at the same place (round 2)", "WITH s AS (SELECT uf, municipio, cod_mun, zona, local, secao, 100.0 * v13 / validos AS pct13 FROM secoes WHERE turno = 2 AND validos >= 50),\nm AS (SELECT uf, cod_mun, zona, local, AVG(pct13) AS media, COUNT(*) AS n FROM s GROUP BY uf, cod_mun, zona, local HAVING n >= 3)\nSELECT s.uf, s.municipio, s.zona, s.local, s.secao, ROUND(s.pct13, 1) AS pct13, ROUND(m.media, 1) AS media_local, ROUND(s.pct13 - m.media, 1) AS diferenca_pp\nFROM s JOIN m USING (uf, cod_mun, zona, local) ORDER BY ABS(s.pct13 - m.media) DESC"],
    ],
    cq_col: {
      uf: "state (abbreviation)", cod_mun: "TSE municipality code", municipio: "municipality name", zona: "electoral zone", secao: "section number", turno: "1 or 2",
      local: "polling place number (unique per zone and municipality)", aptos: "eligible voters", comparecimento: "voters who voted", faltosos: "voters who were absent",
      abertura: "opening time (local time, HH:MM:SS)", encerramento: "closing time (local time)", agregadas: "aggregated sections, if any",
      validos: "valid presidential votes", brancos: "blank votes", nulos: "null votes", vNN: "votes for candidate number NN (e.g. v13, v22)",
      sinalizada: "1 if the section has an anomaly in that round", teste: "test (T01 to T15)", nivel: "a = anomaly, i = informational", categoria: "occurrence category",
      nome: "name", endereco: "address", bairro: "neighborhood", lat: "latitude", lon: "longitude", tipo: "place type (1 to 4)", acessibilidade: "1 = accessible", secoes: "number of sections",
      numero: "candidate number", votos: "votes in Brazil", id: "test code", codigo: "TSE municipality code" },

