    im_n: { s2: "Sections analyzed in round 2", s1: "Sections analyzed in round 1", f2: "Sections with a statistical anomaly in round 2", f1: "Sections with a statistical anomaly in round 1", testes: "Statistical and consistency tests", locais: "Polling places on the site", aptos: "Eligible voters in round 2", comp: "Voted in round 2" },
    im_textos_t: "Ready-made texts", im_curto: "Short (social media)", im_medio: "Medium (brief)", im_longo: "Long (article)",
    im_txt_curto: (v) => `Auditoria BU 2026 analyzed the ${v.s2} sections of Brazil's 2026 runoff with 15 statistical and consistency tests. ${v.f2} sections (${v.p2}) showed a statistical anomaly and were listed for checking. Independent analysis with public TSE data: ${v.url}`,
    im_txt_medio: (v) => `An independent analysis published at ${v.url} checked every section of Brazil's 2026 General Elections with 15 statistical and consistency tests: ${v.s1} in round 1 and ${v.s2} in round 2. In round 2, ${v.f2} sections (${v.p2}) had at least one statistical anomaly; in round 1, ${v.f1} (${v.p1}). The site draws no conclusions about the result: a statistical anomaly shows what to check first, not the cause. The data, the code and the reports are open for anyone to redo the analysis.`,
    im_txt_longo: (v) => [`Auditoria BU 2026 (${v.url}) is an independent statistical analysis of the tally sheets (Boletins de Urna) of Brazil's 2026 General Elections, made only with public data from the Superior Electoral Court (TSE). Every section was analyzed, with no sampling: ${v.s1} in round 1 and ${v.s2} in round 2.`,
      `Each section went through 15 tests, from arithmetic checks (whether the vote total matches the number of voters who voted) to statistical tests on turnout, times and vote distribution. In round 2, ${v.f2} sections (${v.p2}) had at least one statistical anomaly; in round 1, ${v.f1} (${v.p1}). With hundreds of thousands of sections, some of these flags are expected by chance.`,
      `The site does not claim that there was, or was not, fraud or error. A statistical anomaly indicates a checking priority, done with the printed tally sheet, the polling station minutes and the machine's signed files. Anyone can look up their own section, see the polling place, download the data and redo the analysis with the open code published on the site.`].join("\n\n"),
    im_citar_t: "How to cite", im_simples: "Simple", im_abnt: "ABNT", im_apa: "APA",
    im_cit_simples: (v) => `Source: Auditoria BU 2026 — independent analysis of the tally sheets with public TSE data (${v.dom}).`,
    im_cit_abnt: (v) => `${v.autorAbnt}. Auditoria estatística dos Boletins de Urna: Eleições 2026. [S. l.], 2026. Available at: ${v.url}. Accessed on: ${v.hoje}.`,
    im_cit_apa: (v) => `${v.autorApa} (2026). Statistical audit of the tally sheets — 2026 Elections [Auditoria estatística dos Boletins de Urna — Eleições 2026]. ${v.url}`,
    im_palavras_t: "The right words", im_usar: "Use", im_evitar: "Avoid",
