    cq_ex: [
      ["Secciones con 100% para un candidato (2.ª vuelta)", "SELECT uf, municipio, zona, secao, aptos, comparecimento, v13, v22\nFROM secoes\nWHERE turno = 2 AND validos >= 10 AND (v13 = validos OR v22 = validos)\nORDER BY validos DESC"],
      ["Comparecencia por municipio (2.ª vuelta)", "SELECT uf, municipio, COUNT(*) AS secoes, SUM(aptos) AS aptos, SUM(comparecimento) AS votaram,\n  ROUND(100.0 * SUM(comparecimento) / SUM(aptos), 2) AS comparecimento_pct\nFROM secoes WHERE turno = 2\nGROUP BY uf, municipio ORDER BY comparecimento_pct DESC"],
      ["Urnas que cerraron después de las 18 h (hora local)", "SELECT uf, municipio, zona, secao, turno, abertura, encerramento\nFROM secoes WHERE encerramento >= '18:00:00'\nORDER BY encerramento DESC"],
      ["Señalizaciones por prueba y estado", "SELECT s.turno, s.teste, t.nome, s.uf, COUNT(*) AS ocorrencias\nFROM sinalizacoes s JOIN testes t ON t.id = s.teste\nGROUP BY s.turno, s.teste, s.uf ORDER BY ocorrencias DESC"],
      ["Locales con más secciones", "SELECT l.uf, m.nome AS municipio, l.zona, l.local, l.nome, l.bairro, l.secoes\nFROM locais l JOIN municipios m ON m.uf = l.uf AND m.codigo = l.cod_mun\nORDER BY l.secoes DESC"],
      ["Diferencia entre secciones del mismo local (2.ª vuelta)", "WITH s AS (SELECT uf, municipio, cod_mun, zona, local, secao, 100.0 * v13 / validos AS pct13 FROM secoes WHERE turno = 2 AND validos >= 50),\nm AS (SELECT uf, cod_mun, zona, local, AVG(pct13) AS media, COUNT(*) AS n FROM s GROUP BY uf, cod_mun, zona, local HAVING n >= 3)\nSELECT s.uf, s.municipio, s.zona, s.local, s.secao, ROUND(s.pct13, 1) AS pct13, ROUND(m.media, 1) AS media_local, ROUND(s.pct13 - m.media, 1) AS diferenca_pp\nFROM s JOIN m USING (uf, cod_mun, zona, local) ORDER BY ABS(s.pct13 - m.media) DESC"],
    ],
